def _fin(slug, title, short, headline, summary, *, group=JOBS, qualification=False, **kw):
    extra = dict(labels=QUAL_LABELS, exam_heading="Exam levels — papers at each stage", steps_first_label="Entry rule",
                 eligibility=QUAL_ELIGIBILITY, levels_title="What each stage gives you") if qualification else dict(eligibility=FIN_ELIGIBILITY)
    return _guide(slug, title, short, headline, summary, group=group, scope_prefix="Finance", back=BACK, icon="IndianRupee", color="#059669",
                  category="Finance", authority=AUTHORITY, test_topics="", interview_topics="", assignment="", **extra, **kw)


def _fin_hiring(test, interview, task):
    return [
        stage("Round 1 — Resume screening", "Before any test", "Degree, marks, certifications and internships are checked first.",
              [paper("Resume with education, certifications and tools", "PDF", "—", "List Tally/Excel/SAP and any NISM/CA/CMA levels cleared")],
              "Meets the education and certification asked in the job post."),
        stage("Round 2 — Written or online test", "Common for freshers", "Accounting, aptitude and role basics.",
              [paper(test, "MCQ / short answers", "30–90 min (varies)", "Practise timed questions")],
              "Accuracy in accounting and numbers."),
        stage("Round 3 — Technical interview and practical task", "1–2 rounds", "How well you can actually do the work.",
              [paper(interview, "Discussion", "30–60 min", "Explain with real examples"),
               paper(task, "Excel / software task", "30 min – 1 day", "Show clean, checked work")],
              "Clear concepts and correct practical work."),
        stage("Round 4 — HR round and offer", "Final", "Background, expectations and documents.", [],
              "Honest answers; check the offer letter and any bond carefully."),
    ]


def _extra(tools, day, questions):
    return [
        {"id": "tools", "nav": "Tools", "heading": "Tools and software you will use", "columns": ["Tool", "Used for"], "rows": tools},
        {"id": "typical-day", "nav": "A typical day", "heading": "A typical day in this job", "items": day},
        {"id": "interview-questions", "nav": "Interview questions", "heading": "Interview questions to practise", "items": questions},
    ]


def _after(items):
    return [{"id": "after", "nav": "After qualifying", "heading": "What you can do after qualifying", "items": items}]


